19: namespace faiss {
20: 
21: /// The metric space for vector comparison for Faiss indices and algorithms.
22: ///
23: /// Most algorithms support both inner product and L2, with the flat
24: /// (brute-force) indices supporting additional metric types for vector
25: /// comparison.
26: ///
27: /// NOTE: when adding or removing values, update metric_type_from_int()
28: ///       and metric_type_count() below.
29: enum MetricType {
30:     METRIC_INNER_PRODUCT, ///< maximum inner product search
31:     METRIC_L2,            ///< squared L2 search
32:     METRIC_L1,            ///< L1 (aka cityblock)
33:     METRIC_Linf,          ///< infinity distance
34:     METRIC_Lp,            ///< L_p distance, p is given by a faiss::Index
35:                           /// metric_arg
36: 
37:     /// some additional metrics defined in scipy.spatial.distance
38:     METRIC_Canberra = 20,
39:     METRIC_BrayCurtis,
40:     METRIC_JensenShannon,
41: 
42:     /// sum_i(min(a_i, b_i)) / sum_i(max(a_i, b_i)) where a_i, b_i > 0
43:     METRIC_Jaccard,
44:     /// Squared Euclidean distance, ignoring NaNs
45:     METRIC_NaNEuclidean,
46:     /// Gower's distance - numeric dimensions are in [0,1] and categorical
47:     /// dimensions are negative integers
48:     METRIC_GOWER,
49: };
50: 
51: /// all vector indices are this type
52: using idx_t = int64_t;
53: 
54: /// this function is used to distinguish between min and max indexes since
55: /// we need to support similarity and dis-similarity metrics in a flexible way
56: constexpr bool is_similarity_metric(MetricType metric_type) {
57:     return ((metric_type == METRIC_INNER_PRODUCT) ||
58:             (metric_type == METRIC_Jaccard));
59: }
60: 
61: /// Convert an integer to MetricType with range validation.
62: /// Throws FaissException if the value is not a valid MetricType.
63: inline MetricType metric_type_from_int(int x) {
64:     FAISS_THROW_IF_NOT_FMT(
65:             (x >= METRIC_INNER_PRODUCT && x <= METRIC_Lp) ||
66:                     (x >= METRIC_Canberra && x <= METRIC_GOWER),
67:             "invalid metric type %d",
68:             x);
69:     return static_cast<MetricType>(x);
70: }
71: 
72: /// Count of entries in the MetricType enum.
73: constexpr size_t metric_type_count() {
74:     return (METRIC_Lp - METRIC_INNER_PRODUCT) + 1 +
75:             (METRIC_GOWER - METRIC_Canberra) + 1;
76: }
77: 
78: } // namespace faiss
